import {
  Mjml,
  MjmlBody,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlPreview,
  MjmlWrapper,
  MjmlColumn,
  MjmlNavbar,
  MjmlNavbarLink,
  MjmlSection,
  MjmlSpacer,
} from "@faire/mjml-react";
import type { ReactNode } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export const HeaderEmailShell = ({
  children,
  pageBackgroundColor,
  preview,
  theme,
}: {
  children: ReactNode;
  pageBackgroundColor: string;
  preview: string;
  theme: EmailTheme;
}) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{preview}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">{children}</MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

export const HeaderLogo = ({
  align = "left",
  alt,
  href,
  src,
}: {
  align?: "center" | "left" | "right";
  alt: string;
  href: string;
  src: string;
}) => (
  <MjmlImage
    align={align}
    alt={alt}
    href={href}
    padding="0"
    src={src}
    width="55px"
  />
);

export type HeaderWithLogoAndMenuVariant =
  | "menu-right"
  | "menu-left"
  | "menu-around"
  | "stacked-left"
  | "stacked-center"
  | "stacked-right";

export interface HeaderMenuLink {
  href: string;
  label: string;
}

export interface HeaderWithLogoAndMenuProps {
  theme?: EmailTheme;
  logoSrc?: string;
  logoAlt?: string;
  logoHref?: string;
  links?: HeaderMenuLink[];
  pageBackgroundColor?: string;
  backgroundColor?: string;
  textColor?: string;
  variant?: HeaderWithLogoAndMenuVariant;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const defaultLinks: HeaderMenuLink[] = [
  { href: "https://example.com", label: "Home" },
  { href: "https://example.com/about", label: "About us" },
  { href: "https://example.com/shop", label: "Shop" },
  { href: "https://example.com/faq", label: "FAQs" },
  { href: "https://example.com/returns", label: "Returns" },
  { href: "https://example.com/contact", label: "Contact us" },
];

const Menu = ({
  align,
  links,
  textColor,
}: {
  align: "center" | "left" | "right";
  links: HeaderMenuLink[];
  textColor: string;
}) => (
  <MjmlNavbar align={align} padding="0">
    {links.map((link) => (
      <MjmlNavbarLink
        color={textColor}
        fontFamily={fontFamily}
        fontSize="14px"
        href={link.href}
        key={`${link.label}-${link.href}`}
        padding="8px 10px"
      >
        {link.label}
      </MjmlNavbarLink>
    ))}
  </MjmlNavbar>
);

export const HeaderWithLogoAndMenuSection = ({
  backgroundColor = "#fffffe",
  links = defaultLinks,
  logoAlt = "Maizzle",
  logoHref = "https://example.com",
  logoSrc = emailAsset("maizzle-insignia.png"),
  textColor = "#6b7280",
  variant = "menu-right",
}: Omit<HeaderWithLogoAndMenuProps, "theme">) => {
  if (variant.startsWith("stacked-")) {
    const align = variant.replace("stacked-", "") as
      | "center"
      | "left"
      | "right";
    return (
      <MjmlSection backgroundColor={backgroundColor} padding="24px">
        <MjmlColumn padding="0">
          <HeaderLogo
            align={align}
            alt={logoAlt}
            href={logoHref}
            src={logoSrc}
          />
          <MjmlSpacer height="20px" />
          <Menu align={align} links={links} textColor={textColor} />
        </MjmlColumn>
      </MjmlSection>
    );
  }
  if (variant === "menu-around") {
    const midpoint = Math.ceil(links.length / 2);
    return (
      <MjmlSection backgroundColor={backgroundColor} padding="24px">
        <MjmlColumn padding="0" verticalAlign="middle" width="42%">
          <Menu
            align="right"
            links={links.slice(0, midpoint)}
            textColor={textColor}
          />
        </MjmlColumn>
        <MjmlColumn padding="0" verticalAlign="middle" width="16%">
          <HeaderLogo
            align="center"
            alt={logoAlt}
            href={logoHref}
            src={logoSrc}
          />
        </MjmlColumn>
        <MjmlColumn padding="0" verticalAlign="middle" width="42%">
          <Menu
            align="left"
            links={links.slice(midpoint)}
            textColor={textColor}
          />
        </MjmlColumn>
      </MjmlSection>
    );
  }
  const menuLeft = variant === "menu-left";
  const logo = (
    <MjmlColumn padding="0" verticalAlign="middle" width="22%">
      <HeaderLogo
        align={menuLeft ? "right" : "left"}
        alt={logoAlt}
        href={logoHref}
        src={logoSrc}
      />
    </MjmlColumn>
  );
  const menu = (
    <MjmlColumn padding="0" verticalAlign="middle" width="78%">
      <Menu
        align={menuLeft ? "left" : "right"}
        links={links}
        textColor={textColor}
      />
    </MjmlColumn>
  );
  return (
    <MjmlSection backgroundColor={backgroundColor} padding="24px">
      {menuLeft ? menu : logo}
      {menuLeft ? logo : menu}
    </MjmlSection>
  );
};

export const HeaderWithLogoAndMenu = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: HeaderWithLogoAndMenuProps) => (
  <HeaderEmailShell
    pageBackgroundColor={pageBackgroundColor}
    preview="Navigation"
    theme={theme}
  >
    <HeaderWithLogoAndMenuSection {...props} />
  </HeaderEmailShell>
);

HeaderWithLogoAndMenu.PreviewProps = {
  theme: defaultTheme,
  variant: "menu-right",
} satisfies HeaderWithLogoAndMenuProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
